INSERT INTO outbound_message (id, room_target, message_text, reply_to_external_id, status, created_at, sent_at, trigger_message_id, pipeline_run_id) VALUES
('demo-outbound-01', '#general', 'nope. 100 * 0.8 * 1.2 = 96. that is 4% below the starting price. different bases, different result. the receipt wins this argument.', 'demo-message-01', 'SENT', TIMESTAMP '2026-06-15 10:24:04', TIMESTAMP '2026-06-15 10:24:05', 'demo-message-01', 'demo-pipeline-01'),
('demo-outbound-02', '#code', 'b = a gives the same list a second name. use b = a.copy() for a separate outer list; nested lists still share their contents.', 'demo-message-02', 'SENT', TIMESTAMP '2026-06-15 10:21:04', TIMESTAMP '2026-06-15 10:21:05', 'demo-message-02', 'demo-pipeline-02'),
('demo-outbound-03', '#general', 'in a vacuum, they fall with the same acceleration. air resistance is the extra variable, not gravity playing favourites.', 'demo-message-04', 'PENDING', TIMESTAMP '2026-06-15 10:15:04', NULL, 'demo-message-04', 'demo-pipeline-04'),
('demo-outbound-04', '#off-topic', 'when the dream changes what the story means, yes. when it just erases the consequences, that is the writer reaching for the reset button.', 'demo-message-06', 'SENT', TIMESTAMP '2026-06-15 10:09:04', TIMESTAMP '2026-06-15 10:09:05', 'demo-message-06', 'demo-pipeline-05');
