INSERT INTO room_summary (id, room_target, summary, message_count, updated_at, pipeline_run_id) VALUES
('demo-summary-01', '#general', 'James thought a 20% discount followed by 20% tax would cancel out. Alice asked yarik to check. Starting at 100 gives 96, because the second percentage uses a different base. Sophia teased James about inventing free money. Daniel also asked about objects falling in a vacuum.', 42, TIMESTAMP '2026-06-15 09:54:00', 'demo-pipeline-06'),
('demo-summary-02', '#code', 'James is debugging Python list aliasing: b = a points to the same list. A shallow copy separates the outer list but still shares nested objects. Daniel has encountered the same issue. Olivia found that her array was empty and the loop was behaving correctly.', 35, TIMESTAMP '2026-06-15 09:51:00', NULL),
('demo-summary-03', '#off-topic', 'The group is discussing a game''s ending without naming the game. Olivia disliked it. Alice thinks a twist should reframe a story rather than erase it. James asked whether a dream ending can ever work. Ethan left to avoid spoilers.', 28, TIMESTAMP '2026-06-15 09:48:00', NULL);
